steps.action:
curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { teams { id name key members { id name email } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { teams { edges { node { id name key } } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { teams { edges { node { id name members { edges { node { id name email } } } } } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { issues { edges { node { id identifier title state { name } assignee { id name } } } } }"
}'

curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "query { issues(first: 100) { edges { node { id identifier title state { name archivedAt } assignee { id name } } } } }"
}'
